-- ============================================================
-- SEED EXT 2: Módulo 12 — Conditional 2 & 3 (exercícios 71-185)
-- Novos tópicos: wish/if only, formal inversion (Were/Had),
-- should have/could have/might have in Type 3, mixed
-- conditional (present→past), TOEFL academic production
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'conditional-2-3';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo conditional-2-3 não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 11: wish + past simple (present wishes)
  (cid,11,71,'gap_fill','I wish I ___ (speak) more languages — it would open so many doors.','spoke',NULL,'"Wish + past simple" for unreal present wish. (I don''t speak other languages.)','medium'),
  (cid,11,72,'multiple_choice','Which sentence expresses a present wish using "wish" correctly?','She wishes she had more time to conduct research.','["She wishes she has more time to conduct research (present — wrong).","She wishes she would have more time (wrong structure).","She wishes she had more time to conduct research.","She is wishing she had more time (wish not usually continuous)."]','"Wish + past simple" for unreal present situation.','medium'),
  (cid,11,73,'gap_fill','I wish the university ___ (offer) more funding for student research projects.','offered',NULL,'"Wish + past simple" — unreal present: it doesn''t offer enough funding.','medium'),
  (cid,11,74,'gap_fill','He wishes he ___ (be) more confident in academic presentations.','were / was',NULL,'"Wish + were/was" for be-verb in present wishes. "Were" is more formal.','medium'),
  (cid,11,75,'multiple_choice','What does "I wish I knew the answer" mean?','I don''t know the answer now, and I want to.','["I knew the answer in the past","I am going to learn the answer","I don''t know the answer now, and I want to.","I will know the answer soon"]','"Wish + past simple" = unreal present situation (I don''t know).','easy'),
  (cid,11,76,'gap_fill','They wish the equipment ___ (not/be) so expensive — it limits their experiments.','weren''t / wasn''t',NULL,'"Wish + weren''t/wasn''t" for negative present wish.','medium'),
  (cid,11,77,'multiple_choice','Which is INCORRECT?','I wish I would speak better English.','["I wish I could speak better English (ability — correct).","I wish I spoke better English (unreal present — correct).","I wish I would speak better English.","I wish I were more fluent (formal — correct)."]','"Wish + would" is only used for future requests/irritation, NOT for personal present abilities.','hard'),

  -- BLOCK 12: wish + past perfect (past regrets)
  (cid,12,78,'gap_fill','I wish I ___ (choose) a different research topic — this one is much too broad.','had chosen',NULL,'"Wish + past perfect" for regret about a past decision.','hard'),
  (cid,12,79,'multiple_choice','Which sentence expresses a PAST REGRET?','She wishes she had proofread her thesis more carefully.','["She wishes she proofread her thesis (wrong — present wish).","She wished she proofread her thesis (simple past wish — wrong structure).","She wishes she had proofread her thesis more carefully.","She wishes she will proofread her thesis (future — wrong)."]','"Wish + past perfect" for something we regret in the past.','medium'),
  (cid,12,80,'gap_fill','He wishes he ___ (not/drop) out of the program — it was a mistake.','hadn''t dropped',NULL,'"Wish + hadn''t + past participle" = past regret (negative).','hard'),
  (cid,12,81,'gap_fill','We all wish the government ___ (invest) more in science education over the past decade.','had invested',NULL,'"Wish + past perfect" for collective regret about past government policy.','hard'),
  (cid,12,82,'multiple_choice','Compare: "I wish I knew the answer" vs "I wish I had known the answer"','The first is about NOW; the second is about the PAST.','["Both are about the past","The first is about NOW; the second is about the PAST.","The first is past; the second is present","They are identical in meaning"]','Wish + past simple = present; wish + past perfect = past regret.','hard'),
  (cid,12,83,'gap_fill','If only she ___ (submit) the application earlier — she might have been accepted.','had submitted',NULL,'"If only + past perfect" = strong past regret (stronger than "wish").','hard'),
  (cid,12,84,'multiple_choice','Which structure expresses the STRONGEST regret about the past?','If only he had taken the opportunity when it was available.','["He should have taken the opportunity.","He didn''t take the opportunity.","If only he had taken the opportunity when it was available.","He wished to take the opportunity."]','"If only + past perfect" = most emphatic expression of past regret.','hard'),

  -- BLOCK 13: if only / would rather
  (cid,13,85,'gap_fill','If only the data ___ (be) more consistent — it would make the analysis far simpler.','were',NULL,'"If only + past simple" for strong present wish/complaint.','medium'),
  (cid,13,86,'multiple_choice','What is the difference between "I wish" and "If only"?','If only expresses a stronger emotion — more regret or frustration.','["They are identical","If only is more formal","If only expresses a stronger emotion — more regret or frustration.","If only is used only in the past"]','"If only" = more emphatic/emotional version of "I wish."','medium'),
  (cid,13,87,'gap_fill','I''d rather the committee ___ (make) a decision by now — the uncertainty is causing delays.','had made / made',NULL,'"Would rather + subject + past simple (present)" or "had + past participle (past wish)."','hard'),
  (cid,13,88,'multiple_choice','Which sentence uses "would rather" correctly for a PREFERENCE ABOUT ANOTHER PERSON?','I''d rather she submitted her report today than tomorrow.','["I''d rather she submits her report today.","I''d rather she would submit her report today.","I''d rather she submitted her report today than tomorrow.","I''d rather she to submit her report today."]','"Would rather + subject + past simple" for third-person preference.','hard'),
  (cid,13,89,'gap_fill','If only the experiment ___ (succeed) — months of work depended on it.','had succeeded',NULL,'"If only + past perfect" for disappointment about a past outcome.','hard'),

  -- BLOCK 14: formal inversion — Type 2 (Were + subject + to)
  (cid,14,90,'gap_fill','___ the study ___ (were/extend) to a larger sample, its findings would be more reliable.','Were / to be extended / extended',NULL,'Formal Type 2 inversion: Were + subject + to + base verb (formal if-clause replacement).','hard'),
  (cid,14,91,'multiple_choice','Which sentence uses formal Type 2 inversion correctly?','Were the government to invest more in education, outcomes would improve significantly.','["Would the government invest more in education, outcomes would improve.","Were the government invest more in education, outcomes would improve.","Were the government to invest more in education, outcomes would improve significantly.","If the government were investing more in education, outcomes would improve."]','"Were + subject + to + base verb" = formal Type 2 conditional.','hard'),
  (cid,14,92,'gap_fill','___ (were) this hypothesis ___ (prove) correct, it would revolutionize our understanding of cognition.','Were / to be proven / proven',NULL,'Formal inversion: Were + subject + (to be) + past participle (passive).','hard'),
  (cid,14,93,'multiple_choice','The formal sentence "Were the policy to be implemented" is equivalent to:','If the policy were implemented (Type 2)','["If the policy had been implemented (Type 3)","If the policy is implemented (Type 1)","If the policy were implemented (Type 2)","If the policy will be implemented (Type 1)"]','"Were + subject + to be + past participle" = formal Type 2 passive conditional.','hard'),

  -- BLOCK 15: formal inversion — Type 3 (Had + subject + past participle)
  (cid,15,94,'gap_fill','___ (had) the researchers ___ (control) all variables, the results would have been definitive.','Had / controlled',NULL,'Formal Type 3 inversion: Had + subject + past participle = "if they had controlled."','hard'),
  (cid,15,95,'multiple_choice','Which is the formal Type 3 inversion of "If scientists had discovered this earlier, fewer lives would have been lost"?','Had scientists discovered this earlier, fewer lives would have been lost.','["Should scientists discover this earlier, fewer lives would be lost (Type 1 formal).","Were scientists to discover this earlier, fewer lives would be lost (Type 2 formal).","Had scientists discovered this earlier, fewer lives would have been lost.","Discovered had scientists this earlier, fewer lives would be lost."]','"Had + subject + past participle" = formal Type 3 inversion.','hard'),
  (cid,15,96,'gap_fill','___ (had) the government ___ (act) sooner, the economic crisis would have been far less severe.','Had / acted',NULL,'"Had + subject + past participle" = formal "if they had acted."','hard'),
  (cid,15,97,'multiple_choice','Formal Type 3: "Had the team submitted on time, ___."','the results would have been published months earlier.','["the results will be published months earlier","the results would be published months earlier (Type 2 result)","the results would have been published months earlier.","the results had been published months earlier"]','Type 3 result clause: would have + past participle.','medium'),
  (cid,15,98,'gap_fill','___ ___ the experiment ___ (design/passive) differently, the confounding variables ___ (would/eliminate/passive).','Had / been designed / would have been eliminated',NULL,'Type 3 formal inversion with double passive: Had been designed / would have been eliminated.','hard'),

  -- BLOCK 16: could have / might have / should have in Type 3 result clause
  (cid,16,99,'multiple_choice','Which Type 3 result clause expresses PAST POSSIBILITY (not certainty)?','If they had planned better, they might have finished on time.','["If they had planned better, they would have finished on time (certain).","If they had planned better, they must have finished on time (deduction — wrong here).","If they had planned better, they might have finished on time.","If they had planned better, they should have finished on time (obligation/criticism)."]','"Might have" in result clause = uncertain past possibility (it''s possible but not guaranteed).','hard'),
  (cid,16,100,'gap_fill','If the team ___ (follow) the protocol, they ___ (could/avoid) the contamination.','had followed / could have avoided',NULL,'Type 3 with "could have" = past ability/opportunity that wasn''t used.','hard'),
  (cid,16,101,'multiple_choice','What does "If she had submitted earlier, she should have received feedback by now" mean?','It is a Type 3 condition + a past expectation/criticism.','["She definitely received feedback","She submitted earlier","It is a Type 3 condition + a past expectation/criticism.","Should have here means obligation in the if-clause"]','"Should have received" = past expectation (it would be expected/proper to have received feedback).','hard'),
  (cid,16,102,'gap_fill','If we ___ (consider) the ethical implications earlier, we ___ (might/avoid) the controversy entirely.','had considered / might have avoided',NULL,'Type 3 with "might have avoided" = possible past outcome that didn''t happen.','hard'),
  (cid,16,103,'multiple_choice','Choose the Type 3 result using SHOULD HAVE (criticism):','If they had conducted proper testing, they should have caught the error before publication.','["If they had conducted testing, they might have caught the error (possibility).","If they had conducted proper testing, they should have caught the error before publication.","If they had conducted testing, they must have caught the error (deduction).","If they had conducted testing, they would have caught the error (certainty)."]','"Should have caught" = criticism: they ought to have noticed this; it was expected.','hard'),

  -- BLOCK 17: TOEFL Reading — conditionals in academic texts
  (cid,17,104,'multiple_choice','[TOEFL Reading] "Had the Roman Empire not collapsed in 476 CE, European history would have followed a radically different trajectory." This Type 3 conditional is used to:','Evaluate a historical counterfactual — an imagined alternative past.','["Predict future events","Describe a real historical event","Evaluate a historical counterfactual — an imagined alternative past.","Express a general scientific law"]','Type 3 in academic/historical writing = counterfactual analysis.','medium'),
  (cid,17,105,'gap_fill','[TOEFL Reading] "Were the rate of deforestation to continue unchecked, biodiversity loss ___ become irreversible within decades." Best form?','would',NULL,'"Were + subject + to + verb" = formal Type 2 conditional (present/future scenario).','hard'),
  (cid,17,106,'multiple_choice','[TOEFL Reading] "If poverty were eliminated globally, many diseases that disproportionately affect the poor would disappear." This Type 2 conditional expresses:','A hypothetical, currently unrealized scenario about the present or near future.','["A historical event","A scientific fact","A hypothetical, currently unrealized scenario about the present or near future.","A certain future prediction"]','Type 2 = unreal/hypothetical present/future.','medium'),
  (cid,17,107,'gap_fill','[TOEFL Reading] "Had penicillin ___ (discover/passive) earlier, millions of soldiers in World War I might have survived." Best form?','been discovered',NULL,'Type 3 formal inversion: Had + subject + been + past participle.','hard'),
  (cid,17,108,'multiple_choice','[TOEFL Reading] "If we were to take a purely economic approach, social costs would be systematically undervalued." The phrase "if we were to" signals:','A formal Type 2 conditional presenting a hypothetical scenario for analysis.','["A Type 3 counterfactual about the past","A Type 1 conditional about the future","A formal Type 2 conditional presenting a hypothetical scenario for analysis.","A zero conditional for general truths"]','"If + subject + were to + base verb" = formal Type 2 conditional.','hard'),

  -- BLOCK 18: TOEFL Speaking production
  (cid,18,109,'production','[TOEFL Speaking — 45s] Talk about something you regret from the past using wish/if only + past perfect, and about something you wish were different now using wish + past simple.','',NULL,'I wish I had started preparing for the TOEFL earlier — if only I had begun six months ago, I would have had more time to master each skill. Now, I wish I had more flexibility in my schedule to practice daily. If only the test were less expensive, more students would have access to better universities.','hard'),
  (cid,18,110,'production','[TOEFL Speaking — 45s] A reading passage argues that if universities were to abolish tuition fees, access to higher education would increase. Discuss whether you agree, using Type 2 and Type 3 conditionals.','',NULL,'If universities abolished tuition fees, more students from low-income backgrounds would enroll. Were this policy to be adopted globally, inequality in educational outcomes would significantly decrease. Had governments invested more in free public universities decades ago, entire generations would have had greater social mobility. That said, if funding were not redirected from elsewhere, academic quality might suffer.','hard'),
  (cid,18,111,'production','[TOEFL Speaking — 45s] Choose a major historical event and analyze how history would have been different if one key decision had been made differently. Use formal Type 3 inversion.','',NULL,'Had the Cuban Missile Crisis not been resolved diplomatically in 1962, nuclear conflict might have devastated the Northern Hemisphere. Had Khrushchev not agreed to withdraw missiles from Cuba, Kennedy would have been forced to authorize military action. Had that occurred, millions of lives would have been lost and the geopolitical map would have been redrawn entirely.','hard'),

  -- BLOCK 19: TOEFL Writing production
  (cid,19,112,'production','[TOEFL Writing] Write 6 sentences about climate policy using: (1) Type 2 conditional, (2) Type 3 conditional, (3) mixed conditional, (4) wish + past perfect, (5) formal Type 3 inversion, (6) were + to (formal Type 2).','',NULL,'(1) If nations committed to zero emissions by 2030, warming would be limited. (2) If stricter regulations had been implemented in the 1990s, CO₂ levels would not have reached critical thresholds. (3) If the Paris Agreement had been signed earlier, we would be in a much stronger position today. (4) Many scientists wish more attention had been paid to early warnings. (5) Had political will existed in the 1980s, renewable energy would have been developed far sooner. (6) Were all fossil fuel subsidies to be eliminated, investment in clean energy would accelerate dramatically.','hard'),
  (cid,19,113,'production','[TOEFL Writing — Error Correction] Fix all errors: "If I would have studied harder, I would have passed. Had she known, she will have helped. If only he had took the opportunity. Were the policy implemented, outcomes will improve."','',NULL,'If I had studied harder...; Had she known, she would have helped; had taken (not took); outcomes would improve (not will).','hard'),
  (cid,19,114,'production','[TOEFL Writing — 200 words] Write a TOEFL-style body paragraph on the topic "If renewable energy had replaced fossil fuels 50 years ago, what would the world look like today?" Use: at least 3 Type 3 conditionals (including 1 formal inversion), 1 mixed conditional, 1 wish structure, and modal variations (would have / could have / might have).','',NULL,'Had humanity transitioned to renewable energy in the 1970s, atmospheric CO₂ levels would never have reached today''s critical concentrations. Major coastal cities might have been spared the flooding that now threatens millions of residents. Had solar and wind infrastructure been developed decades earlier, the economic disruption associated with today''s emergency transition could have been avoided entirely. Indeed, many economists wish policymakers had heeded the warnings of early climate scientists, who identified the risks as far back as the 1960s. If this transition had occurred, we would currently be living in a world with significantly lower geopolitical tension over energy resources, since fossil fuel dependency has historically fueled international conflict. The mixed consequence, however, is that the technological innovation spurred by today''s energy crisis would not have materialized. Nevertheless, it seems clear that the human and environmental cost of delay has far outweighed any technological silver lining.','hard'),

  -- BLOCK 20: advanced mastery
  (cid,20,115,'multiple_choice','[TOEFL Writing] Which sentence demonstrates the most sophisticated use of conditionals in academic writing?','Were research funding to be restructured toward long-term projects, scientific discovery would not be constrained by the short-term pressures that currently dominate the field.','["If research funding is restructured, science will improve.","If research funding had been restructured, science would have improved.","Were research funding to be restructured toward long-term projects, scientific discovery would not be constrained by the short-term pressures that currently dominate the field.","Research funding should be restructured so that science can improve."]','Formal inversion (Were + to) + complex noun clause + embedded relative clause = highest register.','hard'),
  (cid,20,116,'production','[TOEFL Writing — Capstone] Write a 250-word TOEFL-style essay paragraph arguing that poverty cannot be eliminated without systemic policy reform. Include: Type 2 (×2), Type 3 (×1, with formal inversion), wish + past perfect (×1), mixed conditional (×1), and at least one use of "could have" or "might have" in a result clause.','',NULL,'Poverty is not an inevitable condition; it is the product of policy decisions. If governments were to prioritize redistribution over economic growth, the gap between rich and poor would narrow significantly. Were social safety nets to be strengthened universally, millions of vulnerable citizens would no longer fall below the poverty line when faced with unexpected hardship. Had wealthy nations invested more generously in development aid during the late twentieth century, extreme poverty might have been eradicated decades sooner — many aid economists wish that early commitments to the UN''s 0.7% GDP target had been honored. The mixed conditional reality is equally sobering: if those foundational investments had been made, we would today be facing far fewer of the political crises driven by economic desperation. If we are to succeed in eliminating poverty in the twenty-first century, governments must not simply increase spending — they must reform the structural conditions that reproduce inequality across generations.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
